        "c3abe53f56194761b63d3735fef2e79e": {
          "id": "c3abe53f56194761b63d3735fef2e79e",
          "stepType": "TextOutput",
          "name": "Anmeldung Guidance",
          "secure": false,
          "value": [
            {
              "value": [
                {
                  "type": "paragraph",
                  "children": [
                    {
                      "text": "City Registration (Anmeldung):"
                    }
                  ]
                },
                {
                  "type": "paragraph",
                  "children": [
                    {
                      "text": "You must register your residential address at your local Bürgeramt or Bürgerbüro within 14 days of moving into permanent accommodation."
                    }
                  ]
                },
                {
                  "type": "paragraph",
                  "children": [
                    {
                      "text": ""
                    }
                  ]
                },
                {
                  "type": "paragraph",
                  "children": [
                    {
                      "text": "Key Documents Required:"
                    }
                  ]
                },
                {
                  "type": "paragraph",
                  "children": [
                    {
                      "text": "• Valid Passport/ID"
                    }
                  ]
                },
                {
                  "type": "paragraph",
                  "children": [
                    {
                      "text": "• Completed Wohnungsgeberbestätigung (landlord confirmation form)"
                    }
                  ]
                },
                {
                  "type": "paragraph",
                  "children": [
                    {
                      "text": "• Marriage/Birth certificates (if registering family members)"
                    }
                  ]
                }
              ],
              "mode": "simple",
              "_key": "5f5fbf5a4af14afcb09346efc2e28695"
            }
          ],
          "isCollapsible": true,
          "requestFeedback": true,
          "applicability": {
            "value": "",
            "mode": "query"
          }
        },
        "dc2724b5e22c43069c79c95f0e36b8d8": {
          "id": "dc2724b5e22c43069c79c95f0e36b8d8",
          "stepType": "TextOutput",
          "name": "Tax ID Guidance",
          "secure": false,
          "value": [
            {
              "value": [
                {
                  "type": "paragraph",
                  "children": [
                    {
                      "text": "Tax ID & German Bank Account:"
                    }
                  ]
                },
                {
                  "type": "paragraph",
                  "children": [
                    {
                      "text": "• Tax ID (Steueridentifikationsnummer): It is automatically generated upon completing your Anmeldung and mailed to your registered address in 2 to 4 weeks."
                    }
                  ]
                },
                {
                  "type": "paragraph",
                  "children": [
                    {
                      "text": "• Bank Account: You can open an account at traditional or online German banks using your passport and proof of registration (Meldebescheinigung). Provide your IBAN to HR payroll once active."
                    }
                  ]
                }
              ],
              "mode": "simple",
              "_key": "581de9cfcb9145ef949e746758fdc1c0"
            }
          ],
          "isCollapsible": true,
          "requestFeedback": true,
          "applicability": {
            "value": "",
            "mode": "query"
          }
        },
        "81304dbefc6d42e2829fc1cf7c608e02": {
          "id": "81304dbefc6d42e2829fc1cf7c608e02",
          "stepType": "TextOutput",
          "name": "Check-In Guidance",
          "secure": false,
          "value": [
            {
              "value": [
                {
                  "type": "paragraph",
                  "children": [
                    {
                      "text": "Relocation Pulse Check-In:"
                    }
                  ]
                },
                {
                  "type": "paragraph",
                  "children": [
                    {
                      "text": "Our relocation team triggers scheduled check-ins at 30, 60, and 90 days to help ensure your transition is smooth."
                    }
                  ]
                },
                {
                  "type": "paragraph",
                  "children": [
                    {
                      "text": ""
                    }
                  ]
                },
                {
                  "type": "paragraph",
                  "children": [
                    {
                      "text": "You can complete pending feedback surveys directly from your Retention Portal dashboard or reach out to your relocation coordinator."
                    }
                  ]
                }
              ],
              "mode": "simple",
              "_key": "f3c26976088e420c9eded8c557321f8e"
            }
